--
-- Table structure for table `barangay_families`
--

DROP TABLE IF EXISTS `barangay_families`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `barangay_families` (
  `family_id` int(11) NOT NULL AUTO_INCREMENT,
  `barangay_id` int(11) NOT NULL,
  `family_name` varchar(150) NOT NULL,
  `head_name` varchar(150) DEFAULT NULL,
  `purok` varchar(100) DEFAULT NULL,
  `contact_number` varchar(20) DEFAULT NULL,
  `member_count` int(11) NOT NULL DEFAULT 1,
  `pwd_count` int(11) NOT NULL DEFAULT 0,
  `senior_count` int(11) NOT NULL DEFAULT 0,
  `children_count` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
