--
-- Table structure for table `barangay_food_pack_batches`
--

DROP TABLE IF EXISTS `barangay_food_pack_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `barangay_food_pack_batches` (
  `batch_id` int(11) NOT NULL AUTO_INCREMENT,
  `barangay_id` int(11) NOT NULL,
  `quantity_remaining` int(11) NOT NULL,
  `received_date` date NOT NULL,
  `expiration_date` date NOT NULL,
  `status` enum('active','expired') NOT NULL DEFAULT 'active',
  `expired_at` datetime DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`batch_id`),
  KEY `barangay_id` (`barangay_id`),
  KEY `updated_by` (`updated_by`),
  CONSTRAINT `fk_brgybatch_barangay` FOREIGN KEY (`barangay_id`) REFERENCES `barangays` (`barangay_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_brgybatch_user` FOREIGN KEY (`updated_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=355 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

